<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$viewer=current_user($pdo);$term=trim((string)($_GET['q']??''));$sources=$annotations=$people=[];
if(mb_strlen($term)>=2){$like='%'.$term.'%';$q=$pdo->prepare("SELECT s.public_id,s.title,s.domain,s.canonical_url,s.status FROM sources s WHERE EXISTS(SELECT 1 FROM annotations pa WHERE pa.source_id=s.id AND pa.visibility='public' AND pa.status='published') AND (s.title LIKE ? OR s.domain LIKE ? OR s.canonical_url LIKE ?) ORDER BY s.last_checked_at DESC,s.first_seen_at DESC LIMIT 20");$q->execute([$like,$like,$like]);$sources=$q->fetchAll();$q=$pdo->prepare("SELECT DISTINCT a.public_id,a.text_commentary,a.published_at,u.username,u.display_name,s.public_id source_public_id,s.title,c.selected_text,COALESCE(t.edited_text,t.raw_text) transcript_text FROM annotations a JOIN users u ON u.id=a.user_id JOIN sources s ON s.id=a.source_id JOIN captures c ON c.id=a.capture_id LEFT JOIN annotation_transcripts t ON t.annotation_id=a.id WHERE a.visibility='public' AND a.status='published' AND (a.text_commentary LIKE ? OR c.selected_text LIKE ? OR t.raw_text LIKE ? OR t.edited_text LIKE ? OR s.title LIKE ?) ORDER BY a.published_at DESC LIMIT 30");$q->execute([$like,$like,$like,$like,$like]);$annotations=$q->fetchAll();$q=$pdo->prepare("SELECT u.username,u.display_name,u.bio FROM users u LEFT JOIN user_preferences p ON p.user_id=u.id WHERE u.status='active' AND COALESCE(p.profile_visibility,'public')='public' AND COALESCE(p.search_visibility,1)=1 AND (u.username LIKE ? OR u.display_name LIKE ? OR u.bio LIKE ?) ORDER BY u.display_name LIMIT 20");$q->execute([$like,$like,$like]);$people=$q->fetchAll();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Search · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a><nav><a href="/home.php">Home</a><a href="/explore.php">Explore</a><?php if($viewer):?><a href="/saved.php">Saved</a><a href="/settings.php">Settings</a><?php else:?><a href="/login.php">Log in</a><?php endif?></nav></header><main class="panel"><div class="pageTitle"><div class="eyebrow">DISCOVERY</div><h1>Search Annotated</h1></div><form method="get" class="searchBar"><input name="q" value="<?=h($term)?>" placeholder="Search sources, annotations, transcripts, people" autofocus><button>Search</button></form><?php if($term!==''&&mb_strlen($term)<2):?><div class="error">Enter at least 2 characters.</div><?php endif?><?php if(mb_strlen($term)>=2):?><div class="searchColumns"><section><h2>Sources <span class="meta"><?=count($sources)?></span></h2><?php if(!$sources):?><div class="card">No sources found.</div><?php endif?><?php foreach($sources as $s):?><a class="card sourceCard" href="/source.php?id=<?=h($s['public_id'])?>"><div class="meta"><?=h($s['domain'])?> · <?=h($s['status'])?></div><h3><?=h($s['title']?:$s['canonical_url'])?></h3></a><?php endforeach?></section><section><h2>Annotations & transcripts <span class="meta"><?=count($annotations)?></span></h2><?php if(!$annotations):?><div class="card">No annotations found.</div><?php endif?><?php foreach($annotations as $a):?><article class="card"><div class="meta"><a href="/profile.php?u=<?=h($a['username'])?>"><?=h($a['display_name'])?></a> · <a href="/source.php?id=<?=h($a['source_public_id'])?>"><?=h($a['title']?:'Source')?></a></div><?php if($a['text_commentary']):?><p><?=nl2br(h(mb_substr($a['text_commentary'],0,500)))?></p><?php endif?><?php if($a['transcript_text']):?><details><summary>Transcript match</summary><p><?=nl2br(h(mb_substr($a['transcript_text'],0,900)))?></p></details><?php endif?><a href="/annotation.php?id=<?=h($a['public_id'])?>">Open annotation</a></article><?php endforeach?></section><section><h2>People <span class="meta"><?=count($people)?></span></h2><?php if(!$people):?><div class="card">No people found.</div><?php endif?><?php foreach($people as $p):?><a class="card sourceCard" href="/profile.php?u=<?=h($p['username'])?>"><strong><?=h($p['display_name'])?></strong><div class="meta">@<?=h($p['username'])?></div><?php if($p['bio']):?><p><?=h(mb_substr($p['bio'],0,240))?></p><?php endif?></a><?php endforeach?></section></div><?php endif?></main></body></html>